import * as React from 'react';
import { cn } from '@/lib/utils';

export interface ChainThoughtStep {
  id: string;
  content: string;
  status?: 'pending' | 'completed' | 'failed';
}

export interface ChainThoughtProps {
  steps: ChainThoughtStep[];
  className?: string;
  compact?: boolean;
}

const ChainThought = React.forwardRef<HTMLDivElement, ChainThoughtProps>(
  ({ steps, className, compact = false, ...props }, ref) => {
  if (steps.length === 0) {
    return null;
  }

  return (
    <div ref={ref} className={cn('space-y-2', className)} {...props}>
      {steps.map((step, index) => (
        <div key={step.id} className="flex gap-3 items-start">
          <div className={cn(
            'w-2 h-2 rounded-full mt-1.5 flex-shrink-0',
            step.status === 'completed' ? 'bg-success' : 
            step.status === 'failed' ? 'bg-destructive' : 
            step.status === 'pending' ? 'bg-warning' : 'bg-primary'
          )} />
          <div className={cn('flex-1', compact && 'text-sm')}>
            <div className="text-sm text-muted-foreground">
              Step {index + 1}
            </div>
            <div className="text-foreground">{step.content}</div>
          </div>
        </div>
      ))}
    </div>
  );
});
ChainThought.displayName = 'ChainThought';

export { ChainThought };

{
  "id": "chain-thought",
  "name": "ChainThought",
  "tier": "molecule",
  "description": "Displays ordered reasoning steps with status indicators.",
  "designIntent": "Provide a compact progress view for multi-step agent work.",
  "props": [
    {
      "name": "steps",
      "type": "ChainThoughtStep[]",
      "required": true,
      "description": "Ordered reasoning steps."
    },
    {
      "name": "compact",
      "type": "boolean",
      "defaultValue": false,
      "required": false,
      "description": "Use compact typography."
    }
  ],
  "examples": [
    {
      "title": "Agent steps",
      "code": "<ChainThought steps={[{ id: '1', content: 'Analyzing…', status: 'pending' }]} />"
    }
  ],
  "accessibility": [
    {
      "feature": "Status visibility",
      "implementation": "Each step exposes a text label and visual status."
    }
  ],
  "package": "@slipstream-ui/ai",
  "importPath": "@slipstream-ui/ai",
  "version": "0.0.1",
  "sourceDir": "chainthought",
  "exportName": "ChainThought"
}
